/**
 * @suppress
 */
public object FfiConverterTypeFluyerAppEngine: FfiConverter<FluyerAppEngine, Pointer> {

    override fun lower(value: FluyerAppEngine): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): FluyerAppEngine {
        return FluyerAppEngine(value)
    }

    override fun read(buf: ByteBuffer): FluyerAppEngine {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: FluyerAppEngine) = 8UL

    override fun write(value: FluyerAppEngine, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



